select 

where m.is_delete = 0
and m.match_no like concat('%', #{matchNo}, '%')
and m.season_id = #{seasonId}
and m.stage_id = #{stageId}
and m.round_id = #{roundId}
and m.group_id = #{groupId}
and m.venue_id = #{venueId}
and (m.home_team_id = #{teamId} or m.away_team_id = #{teamId})
and m.match_status = #{matchStatus}
and m.data_status = #{dataStatus}
order by m.scheduled_start_time desc, m.sort_no, m.create_time desc

select count(1) from basket_match
where is_delete = 0 and match_status != 5
  and (home_team_id = #{teamId} or away_team_id = #{teamId})
  and scheduled_start_time < #{endTime}
  and (scheduled_end_time is null or scheduled_end_time > #{startTime})
and id != #{excludeMatchId}

select count(1) from basket_match
where is_delete = 0 and match_status != 5 and venue_id = #{venueId}
  and scheduled_start_time < #{endTime}
  and (scheduled_end_time is null or scheduled_end_time > #{startTime})
and id != #{excludeMatchId}

